import { test } from "node:test";
import assert from "node:assert/strict";
import {
  vpsTerm,
  vpsTermPriceCents,
  vpsEffectiveMonthly,
  addMonths,
  VPS_TERMS,
} from "../lib/billing-terms.ts";

test("vpsTerm returns the matching term by months", () => {
  assert.equal(vpsTerm(1).months, 1);
  assert.equal(vpsTerm(12).discountPct, 10);
  assert.equal(vpsTerm(24).discountPct, 15);
  assert.equal(vpsTerm(36).discountPct, 20);
});

test("vpsTerm falls back to the monthly term for unknown durations", () => {
  assert.deepEqual(vpsTerm(7), VPS_TERMS[0]);
  assert.deepEqual(vpsTerm(0), VPS_TERMS[0]);
  assert.deepEqual(vpsTerm(-5), VPS_TERMS[0]);
});

test("vpsTermPriceCents applies commitment discounts", () => {
  const monthly = 1000; // $10.00/mo
  // 1 mo: no discount
  assert.equal(vpsTermPriceCents(monthly, 1), 1000);
  // 12 mo -10%: 12000 * 0.90 = 10800
  assert.equal(vpsTermPriceCents(monthly, 12), 10800);
  // 24 mo -15%: 24000 * 0.85 = 20400
  assert.equal(vpsTermPriceCents(monthly, 24), 20400);
  // 36 mo -20%: 36000 * 0.80 = 28800
  assert.equal(vpsTermPriceCents(monthly, 36), 28800);
});

test("vpsTermPriceCents rounds to whole cents", () => {
  // 333 * 12 * 0.9 = 3596.4 -> 3596
  assert.equal(vpsTermPriceCents(333, 12), 3596);
});

test("vpsEffectiveMonthly reflects the discounted per-month price", () => {
  // annual $10/mo -> 10800/12 = 900
  assert.equal(vpsEffectiveMonthly(1000, 12), 900);
  // monthly term is unchanged
  assert.equal(vpsEffectiveMonthly(1000, 1), 1000);
});

test("addMonths advances the calendar month", () => {
  const from = new Date("2026-01-15T00:00:00.000Z");
  const plus1 = addMonths(from, 1);
  assert.equal(plus1.getUTCMonth(), new Date("2026-02-15T00:00:00.000Z").getUTCMonth());
  // 12 months forward lands in the next year
  const plus12 = addMonths(from, 12);
  assert.equal(plus12.getUTCFullYear(), from.getUTCFullYear() + 1);
});

test("addMonths does not mutate the input date", () => {
  const from = new Date("2026-03-10T00:00:00.000Z");
  const snapshot = from.getTime();
  addMonths(from, 6);
  assert.equal(from.getTime(), snapshot);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  generateTOTP,
  verifyTOTP,
  generateSecret,
  base32Decode,
  otpauthURL,
} from "../lib/totp.ts";

// RFC 6238 test seed: ASCII "12345678901234567890" as base32, SHA1 mode.
const RFC_SECRET = "GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ";

test("base32Decode round-trips a known RFC 4648 vector", () => {
  // base32("foobar") == "MZXW6YTBOI"
  assert.equal(base32Decode("MZXW6YTBOI").toString("utf8"), "foobar");
});

test("base32Decode is case-insensitive and ignores spaces/padding", () => {
  assert.equal(base32Decode("mzxw 6ytb oi==").toString("utf8"), "foobar");
});

test("base32Decode of the RFC seed yields the ASCII secret", () => {
  assert.equal(base32Decode(RFC_SECRET).toString("utf8"), "12345678901234567890");
});

test("generateTOTP matches RFC 6238 reference vectors (6-digit SHA1)", () => {
  // 8-digit RFC vectors truncated to the low 6 digits.
  assert.equal(generateTOTP(RFC_SECRET, 59_000), "287082"); // T=59
  assert.equal(generateTOTP(RFC_SECRET, 1_111_111_109_000), "081804"); // T=1111111109
  assert.equal(generateTOTP(RFC_SECRET, 1_234_567_890_000), "005924"); // T=1234567890
});

test("generate + verify round-trips at the same instant", () => {
  const secret = generateSecret();
  const at = Date.now();
  const code = generateTOTP(secret, at);
  assert.match(code, /^\d{6}$/);
  assert.equal(verifyTOTP(secret, code, at), true);
});

test("verifyTOTP tolerates +/- one step of clock drift", () => {
  const secret = generateSecret();
  const at = 1_000_000_000_000;
  const code = generateTOTP(secret, at);
  // 30s earlier and later still accepted (window is +/-1 step)
  assert.equal(verifyTOTP(secret, code, at + 30_000), true);
  assert.equal(verifyTOTP(secret, code, at - 30_000), true);
  // Two steps away is outside the window
  assert.equal(verifyTOTP(secret, code, at + 90_000), false);
});

test("verifyTOTP rejects a wrong code", () => {
  const secret = generateSecret();
  const at = Date.now();
  const good = generateTOTP(secret, at);
  const wrong = good === "000000" ? "111111" : "000000";
  assert.equal(verifyTOTP(secret, wrong, at), false);
});

test("verifyTOTP rejects malformed input", () => {
  const secret = generateSecret();
  assert.equal(verifyTOTP(secret, "", Date.now()), false);
  assert.equal(verifyTOTP(secret, "12345", Date.now()), false); // too short
  assert.equal(verifyTOTP(secret, "abcdef", Date.now()), false); // non-numeric
});

test("generateSecret produces a valid base32 secret of expected length", () => {
  const secret = generateSecret();
  assert.match(secret, /^[A-Z2-7]+$/);
  // 20 random bytes -> 32 base32 chars
  assert.equal(secret.length, 32);
  assert.equal(base32Decode(secret).length, 20);
});

test("otpauthURL embeds the secret, issuer and SHA1 params", () => {
  const url = otpauthURL(RFC_SECRET, "user@example.com", "Nxeon");
  assert.ok(url.startsWith("otpauth://totp/"));
  assert.ok(url.includes(`secret=${RFC_SECRET}`));
  assert.ok(url.includes("algorithm=SHA1"));
  assert.ok(url.includes("digits=6"));
  assert.ok(url.includes("period=30"));
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import {
  checkRateLimit,
  resetRateLimit,
  loginRateLimit,
} from "../lib/rate-limit.ts";

const opts = { max: 3, windowMs: 60_000 };

test("checkRateLimit allows up to max hits then blocks", () => {
  const key = `t:${randomUUID()}`;
  const r1 = checkRateLimit(key, opts);
  const r2 = checkRateLimit(key, opts);
  const r3 = checkRateLimit(key, opts);
  const r4 = checkRateLimit(key, opts);

  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);
  assert.equal(r3.ok, true);
  assert.equal(r4.ok, false, "the 4th hit within the window is blocked");
});

test("remaining counts down and hits zero at the limit", () => {
  const key = `t:${randomUUID()}`;
  assert.equal(checkRateLimit(key, opts).remaining, 2);
  assert.equal(checkRateLimit(key, opts).remaining, 1);
  assert.equal(checkRateLimit(key, opts).remaining, 0);
});

test("a blocked result surfaces a positive retryAfterSec", () => {
  const key = `t:${randomUUID()}`;
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  const blocked = checkRateLimit(key, opts);
  assert.equal(blocked.ok, false);
  assert.ok(blocked.retryAfterSec >= 1);
  assert.ok(blocked.retryAfterSec <= 60);
});

test("resetRateLimit clears the window for a key", () => {
  const key = `t:${randomUUID()}`;
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  assert.equal(checkRateLimit(key, opts).ok, false);
  resetRateLimit(key);
  // After reset the key is fresh again.
  assert.equal(checkRateLimit(key, opts).ok, true);
});

test("separate keys are throttled independently", () => {
  const a = `t:${randomUUID()}`;
  const b = `t:${randomUUID()}`;
  checkRateLimit(a, opts);
  checkRateLimit(a, opts);
  checkRateLimit(a, opts);
  assert.equal(checkRateLimit(a, opts).ok, false);
  // b is untouched
  assert.equal(checkRateLimit(b, opts).ok, true);
});

test("loginRateLimit preset allows 5 attempts then blocks", () => {
  const id = randomUUID();
  for (let i = 0; i < 5; i++) {
    assert.equal(loginRateLimit(id).ok, true, `attempt ${i + 1} should be allowed`);
  }
  assert.equal(loginRateLimit(id).ok, false, "6th login attempt is blocked");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  generateReferralCode,
  describeCoupon,
  referralRewardCents,
  signupFreeCreditCents,
} from "../lib/growth.ts";

const AMBIGUOUS = /[01OILil]/; // excluded from the code alphabet

test("generateReferralCode has the default length and unambiguous alphabet", () => {
  const code = generateReferralCode();
  assert.equal(code.length, 7);
  assert.match(code, /^[A-Z2-9]+$/);
  assert.doesNotMatch(code, AMBIGUOUS);
});

test("generateReferralCode honours a custom length", () => {
  assert.equal(generateReferralCode(12).length, 12);
  assert.equal(generateReferralCode(1).length, 1);
});

test("generateReferralCode is effectively unique across many draws", () => {
  const seen = new Set<string>();
  for (let i = 0; i < 500; i++) seen.add(generateReferralCode());
  // 31^7 space -> collisions across 500 draws are vanishingly unlikely.
  assert.equal(seen.size, 500);
});

test("describeCoupon renders each coupon kind", () => {
  assert.equal(describeCoupon({ kind: "PERCENT", value: 20 }), "20% bonus");
  assert.equal(describeCoupon({ kind: "FIXED_CENTS", value: 500 }), "$5.00 off");
  assert.equal(describeCoupon({ kind: "CREDIT_CENTS", value: 1234 }), "$12.34 credit");
});

test("referralRewardCents defaults to 500 and honours a valid env override", () => {
  const prev = process.env.REFERRAL_REWARD_CENTS;
  try {
    delete process.env.REFERRAL_REWARD_CENTS;
    assert.equal(referralRewardCents(), 500);
    process.env.REFERRAL_REWARD_CENTS = "750";
    assert.equal(referralRewardCents(), 750);
    process.env.REFERRAL_REWARD_CENTS = "not-a-number";
    assert.equal(referralRewardCents(), 500);
  } finally {
    if (prev === undefined) delete process.env.REFERRAL_REWARD_CENTS;
    else process.env.REFERRAL_REWARD_CENTS = prev;
  }
});

test("signupFreeCreditCents defaults to 0 when unset", () => {
  const prev = process.env.SIGNUP_FREE_CREDIT_CENTS;
  try {
    delete process.env.SIGNUP_FREE_CREDIT_CENTS;
    assert.equal(signupFreeCreditCents(), 0);
    process.env.SIGNUP_FREE_CREDIT_CENTS = "250";
    assert.equal(signupFreeCreditCents(), 250);
  } finally {
    if (prev === undefined) delete process.env.SIGNUP_FREE_CREDIT_CENTS;
    else process.env.SIGNUP_FREE_CREDIT_CENTS = prev;
  }
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games.ts";

test("GAME_FAMILIES is a non-empty array of lowercase family slugs", () => {
  assert.ok(Array.isArray(GAME_FAMILIES));
